k = int(input())
l = int(input())

if l < k:
    print("NO")
elif l == k:
    print("YES")
    print(0)
elif l % k != 0:
    print("NO")
else:
    # Count how many times we can divide l by k
    count = 0
    current = l

    while current % k == 0:
        current //= k
        count += 1

    if current == 1:
        print("YES")
        print(count - 1)
    else:
        print("NO")
"}

