n, q = map(int, input().split())
painters = []
for _ in range(q):
    l, r = map(int, input().split())
    painters.append((l, r))

# Try all combinations of leaving out 2 painters
max_painted = 0
for i in range(q):
    for j in range(i + 1, q):
        # Leave out painter i and painter j
        # Find the union of all other painters' ranges
        covered = set()
        for k in range(q):
            if k != i and k != j:
                l, r = painters[k]
                for x in range(l, r + 1):
                    covered.add(x)
        max_painted = max(max_painted, len(covered))

print(max_painted)
"}

