import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    n = int(sys.stdin.readline())
    x = list(map(int, sys.stdin.readline().split()))
    x.sort()

    distances = []
    for i in range(1, n):
        distances.append(x[i] - x[i-1])

    if not distances:
        print(0)
        return

    g = distances[0]
    for d in distances[1:]:
        g = math.gcd(g, d)

    m = 0
    for d in distances:
        m += (d - 1)

    print(m)

solve()
"}

