import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    b = list(map(int, data[1:1+n]))

    even_count = 0
    odd_count = 0

    for x in b:
        if x % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    # Keep the larger count, remove the smaller count
    if even_count > odd_count:
        # Remove all odd distances
        result = [x for x in b if x % 2 == 0]
    else:
        # Remove all even distances
        result = [x for x in b if x % 2 != 0]

    # Print the number of elements removed
    removed_count = len(b) - len(result)
    print(removed_count)
    if removed_count > 0:
        print("".join(map(str, [x for x in b if x not in result])))

if __name__ == "__main__":
    solve()
"}

