n = int(input())
nums = list(map(int, input().split()))
total = sum(nums)

if total % 3 != 0:
    print(0)
else:
    target = total // 3
    prefix_sums = [0]

    for i in range(n):
        prefix_sums.append(prefix_sums[-1] + nums[i])

    # Count positions where prefix_sum == 2*target (third piece)
    two_target_positions = []
    for i in range(len(prefix_sums)):
        if prefix_sums[i] == 2 * target:
            two_target_positions.append(i)

    # Count ways to cut
    ways = 0
    for i in range(len(prefix_sums)):
        if prefix_sums[i] == target:
            # Count how many two_target_positions are after i
            count = 0
            for j in two_target_positions:
                if j > i:
                    count += 1
            ways += count

    print(ways)
"}

