n = int(input())
a = list(map(int, input().split()))

MOD = 1000000007

# Find known values and positions
known = []
for i in range(n):
    if a[i] != -1:
        known.append((i, a[i]))

# Available values and positions
available_values = set(range(1, n + 1))
for pos, val in known:
    available_values.discard(val)

unknown_positions = [i for i in range(n) if a[i] == -1]
m = len(unknown_positions)

# DP: dp[mask] = number of ways to assign values to positions in mask
# mask: bit i represents whether we use the i-th unknown position

dp = [0] * (1 << m)
dp[0] = 1

for mask in range(1 << m):
    # Count available values at this point
    used_values = set()
    for bit in range(m):
        if mask & (1 << bit):
            pos = unknown_positions[bit]
            for val in available_values:
                if val == pos + 1:
                    used_values.add(val)

    for pos_idx in range(m):
        if not (mask & (1 << pos_idx)):
            continue
        pos = unknown_positions[pos_idx]
        for val in available_values:
            if val == pos + 1 or val in used_values:
                continue
            new_mask = mask | (1 << pos_idx)
            dp[new_mask] = (dp[new_mask] + dp[mask]) % MOD

print(dp[(1 << m) - 1])
