def main()
    """Read from stdin, compute answer, write to stdout."""
    import sys
    input = sys.stdin.read().split()

    # Skip empty strings
    input = [x for x in input if x]

    t = int(input[0])
    numbers = list(map(int, input[1:1 + t]))

    limit = 10**6

    # Initialize sieve
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False

    # Sieve of Eratosthenes
    for i in range(2, int(limit**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, limit+1, i):
                is_prime[j] = False

    # Mark powers of primes
    is_power_of_prime = [False] * (limit + 1)

    for i in range(2, limit + 1):
        if is_prime[i]:
            power = i
            while power <= limit:
                is_power_of_prime[power] = True
                power *= i

    result = []

    for n in numbers:
        if n == 0:
            result.append(0)
            continue

        if n == 1:
            result.append(1)
            continue

        # Count powers of primes in [2..n]
        count_powers = 0
        for i in range(2, n + 1):
            if is_power_of_prime[i]:
                count_powers += 1

        answer = 1 + (n - 1) - count_powers
        result.append(answer)

    print("\n".join(map(str, result)))

if __name__ == "__main__":
