                return (n//2) + 1 + f(n//2 - 1)
        else:
            # Mr. Chanek takes 1, opponent takes (n-1)/2
            return 1 + ((n-1)//2) + f(((n-1)//2) - 1)

    for _ in range(T):
        N = int(input())
        print(f(N))

