    @lru_cache(maxsize=None)
    def dp(r, s, p):
        if r == 0 and s == 0 and p > 0:
            return (1.0, 0.0, 0.0)
        if r == 0 and s > 0 and p == 0:
            return (0.0, 1.0, 0.0)
        if r > 0 and s == 0 and p == 0:
            return (1.0, 0.0, 0.0)
        if r == 0 and s == 0 and p == 0:
            return (0.0, 0.0, 0.0)

        # Total number of possible pairs
        total_pairs = r * s + s * p + p * r

        # Probability of each transition
        prob_rock_scissors = r * s / total_pairs
        prob_scissors_paper = s * p / total_pairs
        prob_paper_rock = p * r / total_pairs

        # Transition probabilities
        rock_survive = dp(r, s, p - 1)[0]
        scissors_survive = dp(r - 1, s, p)[1]
        paper_survive = dp(r, s - 1, p)[2]

        # Return the probabilities of each species surviving from this state
        return (
            prob_paper_rock * rock_survive + prob_rock_scissors * scissors_survive + prob_scissors_paper * paper_survive,
            prob_paper_rock * scissors_survive + prob_rock_scissors * paper_survive + prob_scissors_paper * rock_survive,
