    for j in range(m-1, -1, -1):
        if i == n-1 and j == 0:
            dp2[i][j] = grid[i][j]
        elif i == n-1:
            if j + 1 < m:
                dp2[i][j] = dp2[i][j+1] + grid[i][j]
            else:
                dp2[i][j] = grid[i][j]
        elif j == 0:
            if i + 1 < n:
                dp2[i][j] = dp2[i+1][j] + grid[i][j]
            else:
                dp2[i][j] = grid[i][j]
        else:
            if j + 1 < m and i + 1 < n:
                dp2[i][j] = max(dp2[i+1][j], dp2[i][j+1]) + grid[i][j]
            elif j + 1 < m:
                dp2[i][j] = dp2[i][j+1] + grid[i][j]
            elif i + 1 < n:
                dp2[i][j] = dp2[i+1][j] + grid[i][j]
            else:
                dp2[i][j] = grid[i][j]

# dp2_end[i][j]: max calories Iahubina can collect from (i,j) to (1,m)
dp2_end = [[0] * m for _ in range(n)]
for i in range(n-1, -1, -1):
    for j in range(m-1, -1, -1):
        if i == 0 and j == m-1:
            dp2_end[i][j] = grid[i][j]
        elif i == 0:
            if j + 1 < m:
                dp2_end[i][j] = dp2_end[i][j+1] + grid[i][j]
            else:
                dp2_end[i][j] = grid[i][j]
        elif j == m-1:
            if i + 1 < n:
                dp2_end[i][j] = dp2_end[i+1][j] + grid[i][j]
            else:
                dp2_end[i][j] = grid[i][j]
        else:
            # Iahubina moves right or up, so from (i+1,j) or (i,j+1)
            if j + 1 < m and i + 1 < n:
                dp2_end[i][j] = max(dp2_end[i+1][j], dp2_end[i][j+1]) + grid[i][j]
            elif j + 1 < m:
                dp2_end[i][j] = dp2_end[i][j+1] + grid[i][j]
            elif i + 1 < n:
                dp2_end[i][j] = dp2_end[i+1][j] + grid[i][j]
            else:
                dp2_end[i][j] = grid[i][j]

# Now find the maximum total gain
max_gain = 0
for i in range(n):
    for j in range(m):
        # Total gain if they meet at (i,j):
        # Iahub: from (1,1) to (i,j) (including) + from (i,j) to (n,m) (excluding)
        # Iahubina: from (n,1) to (i,j) (including) + from (i,j) to (1,m) (excluding)
        # Exclude a[i][j] from both
        iahub = dp1[i][j] + dp1_end[i][j] - grid[i][j]
        iahubina = dp2[i][j] + dp2_end[i][j] - grid[i][j]
        gain = iahub + iahubina
        max_gain = max(max_gain, gain)

print(max_gain)

