import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)
    t = list(s)  # Start with a copy of s

    # Try to flip bits to maximize zeros
    for i in range(n):
        for j in range(i, n):
            # Consider substring s[i..j]
            substr = s[i:j+1]
            # Check if this substring has both 0 and 1
            if '0' in substr and '1' in substr:
                # We need this substring in t to also have both 0 and 1
                # If t currently has all 0s or all 1s in this range, we need to flip
                # at least one bit
                substr_t = t[i:j+1]
                if substr_t.count('0') == 0 or substr_t.count('0') == j - i + 1:
                    # Flip the rightmost 1 to 0 (or leftmost 0 to 1 if all 0s)
                    if substr_t.count('0') == 0:
                        # All 1s, flip leftmost 1 to 0
                        t[i] = '0'
                    else:
                        # All 0s, flip rightmost 1 to 0? Wait, if we have 0s and 1s but want to make all 0s
                        # we need to flip the rightmost 1 to 0
                        t[j] = '0'

    print(''.join(t))

if __name__ == "__main__":
    solve()
