            if freq_b:
                # Use a color from Bob's guess for a rearranged match
                color = next(iter(freq_b))
                a[i] = color
                freq_b[color] -= 1
                y -= 1
            else:
                # No colors left, use a color not in Bob's guess
                a[i] = n + 1
