import sys

# Parse input
lines = sys.stdin.read().splitlines()

# Find throw operation
throw_pos = -1
throw_type = ""

# Parse all operations
operations = []
for i, line in enumerate(lines):
    stripped = line.strip()
    if stripped == "":
        continue

    if stripped == "try":
        operations.append(("try", i))
    elif stripped.startswith("catch"):
        rest = stripped[5:].strip()
        if not rest:
            continue

        # Find the open parenthesis
        type_end = rest.find("(")
        if type_end == -1:
            continue

        # Parse exception type
        type_part = rest[:type_end].strip()

        # Parse message (inside quotes)
        msg_start = rest.find("""", type_end + 1)
        if msg_start == -1:
            msg_start = rest.find("'", type_end + 1)

        if msg_start == -1:
            continue

        # Find the matching quote
        quote_start = msg_start
        if rest[quote_start] == """":
            quote_end = rest.find("""", quote_start)
            if quote_end == -1:
                continue
            quote_end -= 1
        else:
            quote_end = rest.find("'", quote_start)
            if quote_end == -1:
                continue
            quote_end -= 1

        message = rest[quote_start + 1:quote_end].strip()

        operations.append(("catch", i, type_part, message))
    elif stripped.startswith("throw"):
        rest = stripped[5:].strip()
        if not rest:
            continue

        # Find the open parenthesis
        type_end = rest.find("(")
        if type_end == -1:
            continue

        type_part = rest[:type_end].strip()
        type_part = type_part.split(")", 1)[0].strip()

        throw_pos = i
        throw_type = type_part
        operations.append(("throw", i))

# Now find matching catch blocks
matching_catches = []
for op, i, type_part, message in operations:
    if op == "catch" and i > throw_pos:
        if type_part == throw_type:
            matching_catches.append((i, message))

# If no matches
if not matching_catches:
    print("Unhandled Exception")
else:
    # Find which catch block is active
    # The active block is the one that closes the last opened try block

    # Trace through all operations
    stack = []
    result = None

    for op, i, type_part, message in operations:
        if op == "try":
            stack.append((i, i, type_part))  # (start, end, type)
        elif op == "catch":
            if stack:
                start, end, type_part = stack.pop()
                # This catch handles exceptions of type type_part
                if type_part == throw_type and end > throw_pos:
                    result = message
                    break

    print(result if result else "Unhandled Exception")
