import sys
import heapq

def solve():
    n = int(sys.stdin.readline())
    rules = []

    for i in range(4 * n):
        a, b, c = map(int, sys.stdin.readline().split())
        rules.append((a, b, c, i + 1))

    # Initial counts: each server has 4 processes
    counts = {i: 4 for i in range(1, n + 1)}

    # Priority queue: (number_of_processes_on_ai, rule_index, a, b, c)
    heap = []

    # Build initial heap
    for a, b, c, idx in rules:
        heapq.heappush(heap, (-counts[a], idx, a, b, c))

    result = []

    while heap:
        neg_count, idx, a, b, c = heapq.heappop(heap)

        # Apply the rule
        if counts[a] > 0 and counts[b] < 9 and counts[c] < 9:
            result.append(idx)
            counts[a] -= 1
            counts[b] += 1
            counts[c] += 1


    if len(result) == 4 * n:
        print("YES")
        print(" ".join(map(str, result)))
    else:
        print("NO")

if __name__ == "__main__":
    solve()
"}

