from collections import Counter

t = int(input())
for _ in range(t):
    n, x, y = map(int, input().split())
    b = list(map(int, input().split()))

    # Count frequency of each color in Bob's guess
    freq_b = Counter(b)

    # We need to construct Alice's code
    a = []
    used = [False] * (n + 2)  # 1-indexed to n+1

    # Place exact matches first
    for i in range(n):
        if len(a) < x:
            # Use a color from Bob's guess that hasn't been used yet for matching
            for color in freq_b:
                if not used[color]:
                    a.append(color)
                    used[color] = True
                    break
        else:
            # Place a different color
            for c in range(1, n + 2):
                if not used[c]:
                    a.append(c)
                    used[c] = True
                    break

    # Count exact matches and multiset intersection
    exact = 0
    cnt_a = Counter(a)
    for i in range(n):
        if a[i] == b[i]:
            exact += 1

    multiset = 0
    for color in range(1, n + 2):
        multiset += min(freq_b[color], cnt_a[color])

    if exact == x and multiset == y:
        print("YES")
        print(' '.join(map(str, a)))
    else:
        print("NO")
