    l, r = map(int, input().split())
    coverage[l] += 1
    coverage[r + 1] -= 1

# Reconstruct coverage
for i in range(1, n + 1):
    coverage[i] += coverage[i - 1]

# Build the result string
result = []
for i in range(1, n + 1):
    if coverage[i] % 2 == 1:
        result.append('0')  # Rose
    else:
        result.append('1')  # Lily

