n, w, b = map(int, input().split())

# Precompute factorials
fact = [1] * (n + 1)
for i in range(1, n + 1):
    fact[i] = fact[i-1] * i

# Precompute Stirling numbers of the second kind
S = [[0] * (n + 1) for _ in range(n + 1)]
for m in range(n + 1):
    S[m][0] = 0
    if m == 0:
        S[m][1] = 1
    else:
        S[m][1] = 1
        for p in range(2, m + 1):
            S[m][p] = S[m-1][p-1] + p * S[m-1][p]

ways = 0
for i in range(1, n - 1):
    for j in range(1, n - i):
        k = n - i - j
        if k >= 1:
            # First white stripe: i days, w good events
            # Black stripe: j days, b not-so-good events
            # Second white stripe: k days, w good events

            # Number of ways = i! * S(w, i) * j! * S(b, j) * k! * S(w, k)

            ways += fact[i] * S[w][i] * fact[j] * S[b][j] * fact[k] * S[w][k]

print(ways % 1000000009)
