def max_gain(n, m, matrix):
    # DP for Iahub: from (1,1) to (i,j) right/down
    dp_i = [[0] * m for _ in range(n)]
    dp_i[0][0] = matrix[0][0]

    # Iahub moves right/down
    for i in range(n):
        for j in range(m):
            if i > 0:
                dp_i[i][j] = max(dp_i[i][j], dp_i[i-1][j] + matrix[i][j])
            if j > 0:
                dp_i[i][j] = max(dp_i[i][j], dp_i[i][j-1] + matrix[i][j])

    # DP for Iahubina: from (n,1) to (i,j) left/up
    dp_ia = [[0] * m for _ in range(n)]
    dp_ia[n-1][0] = matrix[n-1][0]

    # Iahubina moves left/up
    for i in range(n-1, -1, -1):
        for j in range(1, m):
            if i < n-1:
                dp_ia[i][j] = max(dp_ia[i][j], dp_ia[i+1][j] + matrix[i][j])
            if j < m-1:
                dp_ia[i][j] = max(dp_ia[i][j], dp_ia[i][j-1] + matrix[i][j])

    # Now find the maximum total gain
    max_total = 0
    for i in range(n):
        for j in range(m):
            # Iahub from (1,1) to (i,j) and then to (n,m)
            iahub_part = dp_i[i][j] + dp_i[n-1][m-1] - matrix[i][j]

            # Iahubina from (n,1) to (i,j) and then to (1,m)
            iahubina_part = dp_ia[i][j] + dp_ia[0][m-1] - matrix[i][j]

            total = iahub_part + iahubina_part
            if total > max_total:
                max_total = total

    return max_total

