    # dp[pos][changes][last_char] = max_euphony
    # Position: 0 to len(s)-1
    # Changes: 0 to k
    # Last character: 0 to 25 (a-z)
    # Use 2D array with 1D array of size 26 for last character
    # dp[pos][changes] = array of size 26

    # Initialize with -infinity
    dp = [[[float('-inf')] * 26 for _ in range(k + 1)] for _ in range(len(s))]

    # Base case: position 0 (first character)
    for i in range(26):
        if i == ord(s[0]) - ord('a'):
            # Keep original character
            dp[0][0][i] = 0
        else:
            # Change to this character
            if k > 0:
                dp[0][1][i] = 0

