def max_coins(N):
    if N == 1:
        return 1
    elif N % 2 == 1:
        # N is odd
        # Mr. Chanek takes 1, opponent takes half of (N-1) coins
        # Then the game continues with (N-1)/2 coins
        return 1 + max_coins((N - 1) // 2)
    else:
        # N is even
        # Option 1: Mr. Chanek takes half (N/2) coins
        # Then opponent gets (N-1) coins left
        # Option 2: Mr. Chanek takes 1 coin
        # Then opponent gets (N-1) coins left
        # Opponent will take the option that maximizes their own coins
        # So Mr. Chanek gets N/2 + max_coins(N/2 - 1)
        return N // 2 + max_coins(N // 2 - 1)

