import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    s = data[0]
    k = int(data[1])

    # Read bonus pairs
    n = int(data[2])
    bonus = {}

    idx = 3
    for _ in range(n):
        x = data[idx]
        y = data[idx + 1]
        c = int(data[idx + 2])
        bonus[(x, y)] = c
        idx += 3

    # Map characters to 0-25
    char_to_idx = {chr(ord('a') + i): i for i in range(26)}
    idx_to_char = {i: chr(ord('a') + i) for i in range(26)}

    # DP table: dp[i][j][changes] = max ephony
    # i: 0..len(s), j: 0..25, changes: 0..k
    # We'll use a list of dictionaries for space efficiency
    dp = [{} for _ in range(len(s) + 1)]
    dp[0][char_to_idx[s[0]]][0] = 0  # Starting with first character unchanged

    for i in range(1, len(s)):
        for prev_char, prev_dict in dp[i - 1].items():
            for prev_changes, prev_val in prev_dict.items():
                for curr_char in range(26):
                    curr_changes = prev_changes + (curr_char != char_to_idx[s[i]])
                    if curr_changes > k:
                        continue

                    # Get bonus for (prev_char, curr_char)
                    bonus_val = bonus.get((idx_to_char[prev_char], idx_to_char[curr_char]), 0)

                    # Update DP
                    key = (curr_char, curr_changes)
                    dp[i][curr_char][curr_changes] = max(
                        dp[i].get(key, -float('inf')), 
                        prev_val + bonus_val
                    )

    # Find maximum ephony
    max_val = -float('inf')
    for char, changes_dict in dp[len(s)-1].items():
        for changes, val in changes_dict.items():
            max_val = max(max_val, val)

    print(max_val)

if __name__ == '__main__':
    solve()
"}

