import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    weights = list(map(int, data[1:1+2*n]))

    # Sort weights
    weights.sort()

    min_instability = float('inf')

    # Try all pairs of people to leave in single kayaks
    for i in range(2*n):
        for j in range(i+1, 2*n):
            # Leave i and j unpaired
            instability = 0
            remaining = []
            for k in range(2*n):
                if k != i and k != j:
                    remaining.append(weights[k])

            # Pair remaining people optimally
            # If we have an odd number, we need to leave one more unpaired
            if len(remaining) % 2 != 0:
                # Try leaving each remaining person as the third single kayak
                for l in range(len(remaining)):
                    temp_remaining = remaining[:l] + remaining[l+1:]
                    instability2 = 0
                    for k in range(0, len(temp_remaining)-1, 2):
                        instability2 += abs(temp_remaining[k+1] - temp_remaining[k])
                    instability = min(instability, instability2)
            else:
                # Pair all remaining people
                for k in range(0, len(remaining)-1, 2):
                    instability += abs(remaining[k+1] - remaining[k])

            min_instability = min(min_instability, instability)

    print(min_instability)

if __name__ == "__main__":
    solve()
"}

