import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    juices = []
    idx = 1

    for _ in range(n):
        price = int(data[idx])
        vitamins = data[idx + 1]
        mask = 0
        for ch in vitamins:
            if ch == 'A':
                mask |= 1
            elif ch == 'B':
                mask |= 2
            elif ch == 'C':
                mask |= 4
        juices.append((price, mask))
        idx += 2

    # dp[mask] = minimum cost to get vitamins in mask
    dp = [float('inf')] * 8
    dp[0] = 0

    for price, mask in juices:
        # For all possible current vitamin sets, update with this juice
        # We need to iterate through a copy to avoid modifying during iteration
        for prev_mask in range(8):
            new_mask = prev_mask | mask
            dp[new_mask] = min(dp[new_mask], dp[prev_mask] + price)

    result = dp[7]
    if result == float('inf'):
        print(-1)
    else:
        print(result)

if __name__ == "__main__":
    solve()
"}

