import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    weights = list(map(int, data[1:1+2*n]))
    weights.sort()

    min_instability = float('inf')

    # Try all possible pairs for single kayaks
    for i in range(len(weights)):
        for j in range(i+1, len(weights)):
            # i and j are in single kayaks
            # Remaining people: all except i and j
            remaining = []
            for k in range(len(weights)):
                if k != i and k != j:
                    remaining.append(weights[k])

            # Calculate instability of remaining people when paired optimally
            instability = 0
            for m in range(0, len(remaining) - 1, 2):
                instability += abs(remaining[m] - remaining[m+1])

            min_instability = min(min_instability, instability)

    print(min_instability)

if __name__ == '__main__':
    solve()
"}

