import math

def solve():
    r = int(sys.stdin.readline())

    # We need to find the smallest x such that:
    # r = x^2 + 2xy + x + 1
    # Rearranging: y = (r - 1 - x^2 - x) / (2x)

    # Iterate x from 1 to about sqrt(r)
    for x in range(1, int(math.isqrt(r)) + 2):
        numerator = r - 1 - x*x - x
        if numerator <= 0:
            continue

        if numerator % (2 * x) == 0:
            y = numerator // (2 * x)
            if y > 0:
                print(x, y)
                return

    print("NO")

if __name__ == "__main__":
    solve()
