def is_irreducible(p, k):
    """Check if polynomial p of degree k is irreducible over GF(2)"""
    for d in range(1, k):
        for p1 in range(1, 1 << d):
            if bin(p1).count('1') == 1:
                # Check divisibility
                if p % p1 == 0:
                    return False
    return True


def find_primitive_polynomial(k):
    """Find a primitive polynomial of degree k over GF(2)"""
    for poly in range(1, 1 << k):
        if is_irreducible(poly, k):
            return poly
    return None


def get_coefficients(poly, k):
    """Convert polynomial to coefficients list"""
    coeffs = [0] * k
    for i in range(k):
        if (poly >> i) & 1:
            coeffs[i] = 1
    return coeffs


def generate_sequence(coeffs, k, period):
    """Generate sequence of length period"""
    sequence = [0] * period
    for i in range(k):
        sequence[i] = coeffs[i]
    for i in range(k, period):
        val = 0
        for j in range(k):
            val ^= sequence[i - j - 1] & coeffs[j]
        sequence[i] = val
    return sequence


def find_period(sequence, k):
    """Find the period of the sequence"""
    for i in range(1, len(sequence)):
        if sequence[i:i+k] == sequence[:k]:
            return i
    return -1


def solve(k):
    poly = find_primitive_polynomial(k)
    if poly is None:
        return -1
    coeffs = get_coefficients(poly, k)

    # Find initial values that give period exactly 2k - 1
    for a0 in range(1, 1 << k):
        if bin(a0).count('1') == k:
            # Check if a0 has exactly k ones
            sequence = generate_sequence(coeffs, k, 2 * k - 1)
            period = find_period(sequence, k)
            if period == 2 * k - 1:
                # Output found
                print(' '.join(map(str, coeffs)))
                print(' '.join(map(str, [a0 >> i & 1 for i in range(k)])))
                return

    return -1


solve(int(input()))
