def solve():
    import sys
    sys.setrecursionlimit(1000000)

    def dfs(N, is_my_turn):
        if N == 0:
            return 0

        if is_my_turn:
            # I want to maximize my coins
            if N % 2 == 0:
                option1 = 1 + dfs(N - 1, False)
                option2 = N // 2 + dfs(N // 2, False)
                return max(option1, option2)
            else:
                return 1 + dfs(N - 1, False)
        else:
            # Opponent wants to maximize their coins, which minimizes my coins
            if N % 2 == 0:
                option1 = dfs(N - 1, True)  # opponent takes 1
                option2 = dfs(N // 2, True)  # opponent takes N/2
                return min(option1, option2)
            else:
                return dfs(N - 1, True)

    T = int(input())
    for _ in range(T):
        N = int(input())
        print(dfs(N, True))

solve()
"}

