import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n, k = map(int, data)

    if k > n:
        print("No")
        return

    # Check if n+1 equals k! (k factorial)
    fact = 1
    for i in range(2, k + 1):
        fact *= i
        if fact > n + 1:
            break

    if fact == n + 1:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
"}

