import sys
from math import gcd

def is_triangle(g, x, y):
    """Check if g, x, y can form a triangle"""
    return g + x > y and g + y > x and x + y > g

def has_friend(a, n):
    """Check if a has a friend in the group 1..n"""
    for b in range(1, a):
        if a <= n and b <= n:
            g = gcd(a, b)
            x = a // g
            y = b // g
            if is_triangle(g, x, y):
                return True
    return False

def count_lonely(n):
    """Count lonely numbers from 1 to n"""
    count = 0
    for a in range(1, n + 1):
        if not has_friend(a, n):
            count += 1
