    B = list(map(int, data[1:1+n]))

    # Compute gcd of all elements in B
    from math import gcd
    current_gcd = B[0]
    for b in B[1:]:
        current_gcd = gcd(current_gcd, b)
        if current_gcd == 1:
            break  # GCD of 1 means we're done

    # We need to remove all elements that are not relatively prime with the gcd
    # This means we remove all elements that have a common factor with the gcd
    # The remaining elements are relatively prime with the gcd, and the graph is bipartite

    # Find all elements that are not relatively prime with current_gcd
    to_remove = []
    for b in B:
        if gcd(b, current_gcd) != 1:
