    # Base cases: only one species left
    for i in range(r+1):
        for j in range(s+1):
            for k in range(p+1):
                if i == 0 and j == 0:
                    # Only paper left
                    dp[i][j][k] = [0.0, 0.0, 1.0]
                elif i == 0 and k == 0:
                    # Only scissors left
                    dp[i][j][k] = [0.0, 1.0, 0.0]
                elif j == 0 and k == 0:
                    # Only rock left
                    dp[i][j][k] = [1.0, 0.0, 0.0]
                else:
                    # Not an absorbing state
                    dp[i][j][k] = [0.0, 0.0, 0.0]

    # Fill DP table in reverse
    for i in range(r, -1, -1):
        for j in range(s, -1, -1):
            for k in range(p, -1, -1):
                if i == 0 and j == 0:
                    continue
                if i == 0 and k == 0:
                    continue
                if j == 0 and k == 0:
                    continue

                # Total interactions
                total = 2 * i * j + 2 * j * k + 2 * k * i
                if total == 0:
                    continue

                # Transition probabilities
                prob_r_s = (2 * i * j) / total
                prob_s_p = (2 * j * k) / total
                prob_p_r = (2 * k * i) / total

                # Expected probabilities from transitions
                expected_r = prob_r_s * dp[i-1][j-1][k][0] + prob_s_p * dp[i][j-1][k-1][0] + prob_p_r * dp[i-1][j][k-1][0]
