import sys
from collections import deque

def bfs_level(source, sink, level, graph, n, m):
    """
    Perform BFS to compute levels for Dinic's algorithm.
    """
    for i in range(n):
        for j in range(m):
            level[(i, j)] = -1

    queue = deque()
    queue.append((source[0], source[1]))
    level[(source[0], source[1])] = 0

    while queue:
        i, j = queue.popleft()
        current_capacity = graph[(i, j)][0]

        # Move right
        if j + 1 < m and level[(i, j+1)] == -1 and current_capacity > 0:
            level[(i, j+1)] = level[(i, j)] + 1
            queue.append((i, j+1))

        # Move down
        if i + 1 < n and level[(i+1, j)] == -1 and current_capacity > 0:
            level[(i+1, j)] = level[(i, j)] + 1
            queue.append((i+1, j))


def dfs_flow(start, end, flow, graph, level, ptr, n, m):
    """
    DFS to find blocking flow in Dinic's algorithm.
    """
    if start == end:
        return flow

    while ptr[(start)] < len(graph[(start)]):
        i, j = start
        to_i, to_j, capacity = graph[(i, j)][ptr[(start)]]

        if level[(i, j)] + 1 == level[(to_i, to_j)] and capacity > 0:
            min_flow = min(flow, capacity)
            result = dfs_flow((to_i, to_j), end, min_flow, graph, level, ptr, n, m)

            if result > 0:
                graph[(i, j)][ptr[(start)]] = (to_i, to_j, capacity - result)
                graph[(to_i, to_j)].append((i, j, result))
                return result

            ptr[(start)] += 1
        else:
            ptr[(start)] += 1

    return 0


def max_flow(source, sink, graph, n, m):
    """
    Dinic's algorithm to compute max flow.
    """
    flow = 0

    while True:
        level = {}
        bfs_level(source, sink, level, graph, n, m)

        if level[sink] == -1:
            break

        ptr = {cell: 0 for cell in graph}

        while True:
            pushed = dfs_flow(source, sink, float('inf'), graph, level, ptr, n, m)
            if pushed == 0:
                break
            flow += pushed

    return flow


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    grid = []
    for _ in range(n):
        row = data[idx]; idx += 1
        grid.append(list(row))

    # Create graph: (i, j) -> list of (to_i, to_j, capacity)
    graph = {}
    for i in range(n):
        for j in range(m):
            # Add self-loop for vertex capacity
            graph[(i, j)] = [(i, j, 1)]

            # Move right
            if j + 1 < m:
                graph[(i, j)].append((i, j+1, 1))

            # Move down
            if i + 1 < n:
                graph[(i, j)].append((i+1, j, 1))

    source = (0, 0)
    sink = (n-1, m-1)

    # Add super source
    graph[source].append((source, sink, 1))

    # Add super sink
    for i in range(n):
        for j in range(m):
            if (i, j) == source:
                continue
            graph[sink].append((sink, (i, j), 1))

    result = max_flow(source, sink, graph, n, m)

    print(result)

if __name__ == "__main__":
    solve()
