import sys

def parse_command_line(s):
    """
    Parse a Windows command line string and return a list of lexemes.
    """
    tokens = []
    current_token = []
    in_quotes = False

    for char in s:
        if char == """:
            if in_quotes:
                # Closing quote, finish the current token
                tokens.append("".join(current_token))
                current_token = []
                in_quotes = False
            else:
                # Opening quote, start a new quoted token
                tokens.append("".join(current_token))
                current_token = []
                in_quotes = True
        elif char == " " and not in_quotes and len(current_token) > 0:
            # Space outside quotes, finish the current token
            tokens.append("".join(current_token))
            current_token = []
        else:
            # Regular character, add to current token
            current_token.append(char)

    # Add the last token if there is one
    if len(current_token) > 0:
        tokens.append("".join(current_token))

    return tokens

def main():
    s = sys.stdin.readline().strip()
    lexemes = parse_command_line(s)

    for i, lexeme in enumerate(lexemes):
        print(f"<{lexeme}>")

if __name__ == "__main__":
    main()
