import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        x = int(next(it))
        y = int(next(it))
        bob = [int(next(it)) for _ in range(n)]

        # We need to find Alice's code
        # Create a list of available colors
        freq = {}
        for color in bob:
            freq[color] = freq.get(color, 0) + 1

        # We need y exact matches in total
        # For the first x positions, we'll keep them as exact matches
        alice = bob[:x].copy()

        # For the remaining positions, we need to fill them with colors
        # that already exist in Bob's guess but not in the exact match positions
        used_exact = set(bob[:x])

        # We need y-x more matches from the remaining positions
        needed = y - x

        i = x
        while i < n and needed > 0:
            # Find a color in Bob's guess that's not already used in exact matches
            # and has remaining frequency
            found = False
            for color in freq:
                if freq[color] > 0 and color not in used_exact:
                    # Use this color for the current position
                    alice.append(color)
                    freq[color] -= 1
                    needed -= 1
                    found = True
                    break
            if not found:
                # No more colors to match
                break
            i += 1

        # Check if we could fill all positions
        if i < n:
            # We need to fill remaining positions with other colors
            # Just use colors that are not in exact matches
            for color in freq:
                if freq[color] > 0 and color not in used_exact:
                    alice.append(color)
                    freq[color] -= 1

        # Now check if the answer is valid
        # Count exact matches
        exact_matches = 0
        for i in range(n):
            if alice[i] == bob[i]:
                exact_matches += 1

        # Count multiset intersection size
        multiset_intersection = 0
        count_bob = {}
        count_alice = {}
        for color in bob:
            count_bob[color] = count_bob.get(color, 0) + 1
        for color in alice:
            count_alice[color] = count_alice.get(color, 0) + 1

        # Find intersection
        for color in count_bob:
            if color in count_alice:
                multiset_intersection += min(count_bob[color], count_alice[color])

        if exact_matches == x and multiset_intersection == y:
            out_lines.append("YES")
            out_lines.append(" ".join(map(str, alice)))
        else:
            out_lines.append("NO")

