        if divides_polynomial(p, d):
            return False

    return True

def is_irreducible(p, k):
    """Check if the polynomial p of degree k is irreducible over GF(2)"""
    if sum(p) == 0:
        return False  # Constant polynomial
    if sum(p) < 2:
        return False  # Not all coefficients are 1

