    n, k, M = map(int, input().split())
    times = list(map(int, input().split()))

    # Precompute prefix sums
    prefix = [0] * (k + 1)
    for i in range(1, k + 1):
        prefix[i] = prefix[i - 1] + times[i - 1]

    # dp[i][j] = max points using first i tasks with j minutes left
    dp = [[0] * (M + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(M + 1):
            # Option 1: don't solve any subtasks from this task
            dp[i][j] = max(dp[i][j], dp[i - 1][j])

            # Option 2: solve m subtasks from this task
            for m in range(1, k + 1):
                cost = prefix[m]
                if j >= cost:
                    dp[i][j] = max(dp[i][j], dp[i - 1][j - cost] + m)

    print(dp[n][M])

