def solve():
    T = int(input())
    results = []

    for _ in range(T):
        N = int(input())

        # If N is odd, Mr. Chanek takes 1 coin, then it's opponent's turn with N-1 coins
        # If N is even, Mr. Chanek takes half of the coins, then it's opponent's turn with N/2 coins
        # We need to find the maximum coins Mr. Chanek can get

        def dfs(n, turn):
            # turn: 0 for Mr. Chanek's turn, 1 for opponent's turn
            if n == 0:
                return 0

            if turn == 0:
                # Mr. Chanek's turn
                if n % 2 == 1:
                    # Must take 1 coin
                    return 1 + dfs(n-1, 1)
                else:
                    # Can take 1 coin or half
                    return max(1 + dfs(n-1, 1), n//2 + dfs(n//2, 1))
            else:
                # Opponent's turn
                if n % 2 == 1:
                    # Must take 1 coin
                    return 1 + dfs(n-1, 0)
                else:
                    # Can take 1 coin or half
                    return max(1 + dfs(n-1, 0), n//2 + dfs(n//2, 0))

        results.append(dfs(N, 0))

    for res in results:
        print(res)

