import sys

def are_remainders_distinct(n, k):
    if k > n:
        return False  # Too many values, some will have the same remainder

    seen = set()
    for i in range(1, k + 1):
        remainder = n % i
        if remainder in seen:
            return False
        seen.add(remainder)
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])

    if are_remainders_distinct(n, k):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
"}

