def min_layers(N):
    """Find the minimum number of layers to draw all segments on coordinate axis from 0 to N."""
    segments = []

    # Generate all segments
    for i in range(N + 1):
        for j in range(i + 1, N + 1):
            segments.append((i, j))

    # Greedily place segments into layers
    layers = []

    for (start, end) in segments:
        placed = False
        for layer in layers:
            # Check if this segment overlaps with any in the layer
            # Two segments [a, b] and [c, d] overlap if max(a, c) < min(b, d)
            overlap = False
            for (a, b) in layer:
                if max(start, a) < min(end, b):
                    overlap = True
                    break

            if not overlap:
                layer.append((start, end))
                placed = True
                break

        if not placed:
            layers.append([(start, end)])

    return len(layers)

N = int(input())
print(min_layers(N))
