# For each point, store its neighbors in sorted order
neighbors = [[] for _ in range(n + 1)]
for _ in range(m):
    u, v = map(int, input().split())
    if u > v:
        u, v = v, u
    neighbors[u].append(v)
    neighbors[v].append(u)

# Sort neighbors for each point
for i in range(1, n + 1):
    neighbors[i].sort()

# dp[i] = maximum tail length ending at point i
# degree[i] = number of neighbors of point i
# count_greater[i] = number of neighbors > i
dp = [1] * (n + 1)
degree = [0] * (n + 1)
count_greater = [0] * (n + 1)

for i in range(1, n + 1):
    for j in neighbors[i]:
        degree[i] += 1
        if j > i:
            count_greater[i] += 1

    # Compute dp[i]
    for j in neighbors[i]:
        if j < i:
            dp[i] = max(dp[i], dp[j] + 1)

# Compute maximum beauty
max_beauty = 0
for i in range(1, n + 1):
    beauty = dp[i] * (degree[i] - count_greater[i])
    if beauty > max_beauty:
        max_beauty = beauty

print(max_beauty)
