import sys

def solve() -> None:
    n = int(sys.stdin.readline())
    x_list = []
    y_list = []
    for _ in range(n):
        x, y = map(int, sys.stdin.readline().split())
        x_list.append(x)
        y_list.append(y)

    sum_x = sum(x_list)
    sum_y = sum(y_list)

    if (sum_x + sum_y) % 2 != 0:
        print(-1)
        return

    required = sum_y % 2
    cnt = 0
    for i in range(n):
        a = x_list[i] % 2
        b = y_list[i] % 2
        if a != b:
            cnt += 1

    if cnt == 0:
        if required == 0:
            print(0)
        else:
            print(-1)
    else:
        print(0 if required == 0 else 1)

if __name__ == "__main__":
