all_sections = set()
for p in painters:
    all_sections.update(p)
total = len(all_sections)

# Calculate sections painted only by each painter
only_painter = [set() for _ in range(q)]
for i in range(q):
    for x in painters[i]:
        only_painter[i].add(x)
    # Remove sections painted by other painters
    for j in range(q):
        if j != i:
            only_painter[i] -= painters[j]

max_painted = 0

# Try leaving out each pair of painters
for i in range(q):
    for j in range(i + 1, q):
        # Calculate sections painted by all except painter i and j
        # = total - sections only painted by i - sections only painted by j
        painted = total - len(only_painter[i]) - len(only_painter[j])
        max_painted = max(max_painted, painted)

print(max_painted)
