upper_sum = sum(x for x, y in dominoes)
lower_sum = sum(y for x, y in dominoes)

def is_even(s):
    return s % 2 == 0

# If both sums are even, no rotations needed
if is_even(upper_sum) and is_even(lower_sum):
    print(0)
else:
    # Count dominoes with different parity (one odd, one even)
    diff_parity = 0
    for x, y in dominoes:
        if (x % 2) != (y % 2):
            diff_parity += 1

    # If both sums are odd, we need 1 rotation
    if not is_even(upper_sum) and not is_even(lower_sum):
        if diff_parity >= 1:
            print(1)
        else:
            print(-1)
    else:
        # One sum is even, one is odd
        # We need 1 rotation
        if diff_parity >= 1:
            print(1)
        else:
            print(-1)
