import math

def solve():
    r = int(input().strip())

    found = False

    # Iterate x from 1 to sqrt(r)
    for x in range(1, int(math.isqrt(r)) + 1):
        # Check if x divides (r - 1)
        if (r - 1) % x == 0:
            # Compute y
            numerator = r - x*x - x - 1
            if numerator > 0 and numerator % (2*x) == 0:
                y = numerator // (2*x)
                print(x, y)
                found = True
                break

    if not found:
        print("NO")

solve()
"}

