{"code": "
def is_palindrome(s, left, right):
    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1
    return True

s = input().strip()

# Find all palindromic substrings
palindromes = []
for start in range(len(s)):
    for end in range(start, len(s)):
        if is_palindrome(s, start, end):
            palindromes.append((start, end))

# Count valid pairs
count = 0
for i, (s1, e1) in enumerate(palindromes):
    for j, (s2, e2) in enumerate(palindromes):
        if i < j and e1 < s2:
            count += 1

print(count)
"}

